     [RelayCommand]
     private void ClearLog() => LogOutput = string.Empty;

     [RelayCommand]
     private void SaveL5xGitPath()
     {
         PersistConfig();
         AppendLog($"[settings] l5xgit.exe path saved: {L5xGitExePath}");
     }

     // -------------------------------------------------------------------------
     // CanExecute predicates
     // -------------------------------------------------------------------------

     private bool HasSelectedRepo() => SelectedRepo is not null;

     private bool CanCommit() =>
         SelectedRepo is not null &&
         !string.IsNullOrWhiteSpace(CommitMessage) &&
         !IsBusy;

     private bool CanPullAndRestore() =>
         SelectedRepo is not null && !IsBusy;

     // -------------------------------------------------------------------------
     // Helpers
     // -------------------------------------------------------------------------

     private void AppendLog(string message)
     {
         var ts = DateTime.Now.ToString("HH:mm:ss");
         Application.Current?.Dispatcher.Invoke(() =>
         {
             LogOutput += $"[{ts}] {message}\n";
         });
     }

     private void PersistConfig()
     {
         _config.L5xGitExePath = L5xGitExePath;
         _config.Repos = [.. Repos.Select(r => r.ToModel())];
         _configService.Save(_config);
     }
