 using System.IO;
 using System.Text.Json;
 using ABLogixGitManager.Models;

 namespace ABLogixGitManager.Services;

 /// <summary>
 /// Loads and saves the application configuration to
 /// %APPDATA%\ABLogixGitManager\config.json.
 /// </summary>
 public class AppConfigService
 {
     private static readonly string ConfigDir = Path.Combine(
         Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
         "ABLogixGitManager");

     private static readonly string ConfigFilePath = Path.Combine(ConfigDir, "config.json");

     private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

     public AppConfig Load()
     {
         if (!File.Exists(ConfigFilePath))
             return new AppConfig();

         try
         {
             var json = File.ReadAllText(ConfigFilePath);
             return JsonSerializer.Deserialize<AppConfig>(json, JsonOptions) ?? new AppConfig();
         }
         catch
         {
             return new AppConfig();
         }
     }

     public void Save(AppConfig config)
     {
         Directory.CreateDirectory(ConfigDir);
         File.WriteAllText(ConfigFilePath, JsonSerializer.Serialize(config, JsonOptions));
     }
 }

