1. using System.Diagnostics;
2. using System.IO;
3. using ABLogixGitManager.Models;
4. 
5. namespace ABLogixGitManager.Services;
6. 
7. /// <summary>
8. /// Shells out to l5xgit.exe (and git) to perform commit and pull/restore operations.
9. /// Streams stdout/stderr back to the caller via the <paramref name="onOutput"/> callback.
10. /// </summary>
11. public class L5xGitCliService
12. {
13.     // -------------------------------------------------------------------------
14.     // Public API
15.     // -------------------------------------------------------------------------
16. 
17.     /// <summary>
18.     /// Writes the _L5xGit.yml sidecar, then runs:
19.     ///   l5xgit commit --acd "&lt;acdPath&gt;"
20.     /// Pipes the commit message to stdin (blank line ends the prompt loop).
21.     /// </summary>
22.     public async Task CommitAsync(
23.         RepoEntry repo,
24.         string l5xGitExePath,
25.         string commitMessage,
26.         Action<string> onOutput,
27.         CancellationToken cancellationToken = default)
28.     {
29.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
30. 
31.         // Blank line after the message signals end-of-input to PromptForCommitMessage.
32.         var stdin = commitMessage.Trim() + "\n\n";
33. 
34.         await RunProcessAsync(
35.             exePath: l5xGitExePath,
36.             arguments: $"commit --acd \"{repo.AcdFilePath}\"",
37.             workingDir: null,
38.             stdinInput: stdin,
39.             onOutput: onOutput,
40.             cancellationToken: cancellationToken);
41.     }
42. 
43.     /// <summary>
44.     /// Runs:
45.     ///   git -C "&lt;gitRepoPath&gt;" pull
46.     /// then:
47.     ///   l5xgit restoreacd --acd "&lt;acdPath&gt;"
48.     /// Pipes "y" to stdin to confirm overwriting the existing ACD file.
49.     /// </summary>
50.     public async Task PullAndRestoreAsync(
51.         RepoEntry repo,
52.         string l5xGitExePath,
53.         Action<string> onOutput,
54.         CancellationToken cancellationToken = default)
55.     {
56.         onOutput("[git pull] Pulling latest from remote...");
57.         await RunProcessAsync(
58.             exePath: "git",
59.             arguments: $"-C \"{repo.GitRepoPath}\" pull",
60.             workingDir: null,
61.             stdinInput: null,
62.             onOutput: onOutput,
63.             cancellationToken: cancellationToken);
64. 
65.         if (cancellationToken.IsCancellationRequested) return;
66. 
67.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
68. 
69.         onOutput("[restoreacd] Imploding and converting to ACD...");
70.         await RunProcessAsync(
71.             exePath: l5xGitExePath,
72.             arguments: $"restoreacd --acd \"{repo.AcdFilePath}\"",
73.             workingDir: null,
74.             stdinInput: "y\n",   // confirm overwrite of existing ACD
75.             onOutput: onOutput,
76.             cancellationToken: cancellationToken);
77.     }
78. 
79.     // -------------------------------------------------------------------------
80.     // Private helpers
81.     // -------------------------------------------------------------------------
82. 
83.     /// <summary>
84.     /// Writes (or overwrites) the {name}_L5xGit.yml sidecar file next to the ACD.
85.     /// The l5xgit CLI looks for this file to know where the git repo lives.
86.     /// Format mirrors L5xGitConfig YAML serialization.
87.     /// </summary>
88.     private static void EnsureL5xGitYml(string acdFilePath, string gitRepoPath)
89.     {
90.         var dir = Path.GetDirectoryName(acdFilePath) ?? string.Empty;
91.         var stem = Path.GetFileNameWithoutExtension(acdFilePath);
92.         var configPath = Path.Combine(dir, $"{stem}_L5xGit.yml");
93. 
94.         // YamlDotNet uses forward-slash paths; backslashes are valid in YAML
95.         // scalars but can confuse some parsers — use forward slashes to be safe.
96.         var normalizedPath = gitRepoPath.Replace('\\', '/');
97. 
98.         var yaml =
99.             $"destination_path: {normalizedPath}\n" +
100.             $"prompt_for_commit_message: true\n";
101. 
102.         File.WriteAllText(configPath, yaml);
103.     }
104. 
105.     private static async Task RunProcessAsync(
106.         string exePath,
107.         string arguments,
108.         string? workingDir,
109.         string? stdinInput,
110.         Action<string> onOutput,
111.         CancellationToken cancellationToken)
112.     {
113.         var psi = new ProcessStartInfo
114.         {
115.             FileName = exePath,
116.             Arguments = arguments,
117.             WorkingDirectory = workingDir ?? string.Empty,
118.             RedirectStandardInput = true,
119.             RedirectStandardOutput = true,
120.             RedirectStandardError = true,
121.             UseShellExecute = false,
122.             CreateNoWindow = true,
123.         };
124. 
125.         using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };
126. 
127.         process.OutputDataReceived += (_, e) =>
128.         {
129.             if (e.Data is not null) onOutput(e.Data);
130.         };
131.         process.ErrorDataReceived += (_, e) =>
132.         {
133.             if (e.Data is not null) onOutput($"[stderr] {e.Data}");
134.         };
135. 
136.         process.Start();
137.         process.BeginOutputReadLine();
138.         process.BeginErrorReadLine();
139. 
140.         if (stdinInput is not null)
141.         {
142.             await process.StandardInput.WriteAsync(stdinInput);
143.         }
144.         process.StandardInput.Close();
145. 
146.         await process.WaitForExitAsync(cancellationToken);
147. 
148.         if (process.ExitCode != 0)
149.             onOutput($"[exit code {process.ExitCode}] Operation may have encountered errors.");
150.         else
151.             onOutput("[done] ✓ Operation completed successfully.");
152.     }
153. }
154.

