using System.Windows;
using System.Windows.Controls;

namespace ABLogixGitManager.Controls;

/// <summary>
/// A <see cref="StackPanel"/> with a <see cref="Spacing"/> dependency property that inserts
/// a uniform gap between children without requiring a <c>Margin</c> on each child element.
/// Collapsed children are skipped and do not contribute to the spacing budget.
/// </summary>
public class SpacedStackPanel : StackPanel
{
    public static readonly DependencyProperty SpacingProperty =
        DependencyProperty.Register(
            nameof(Spacing),
            typeof(double),
            typeof(SpacedStackPanel),
            new FrameworkPropertyMetadata(
                0.0,
                FrameworkPropertyMetadataOptions.AffectsMeasure | FrameworkPropertyMetadataOptions.AffectsArrange));

    /// <summary>Gets or sets the uniform gap (pixels) between children.</summary>
    public double Spacing
    {
        get => (double)GetValue(SpacingProperty);
        set => SetValue(SpacingProperty, value);
    }

    protected override Size MeasureOverride(Size constraint)
    {
        var spacing = Spacing;
        if (spacing <= 0)
            return base.MeasureOverride(constraint);

        var isHorizontal = Orientation == Orientation.Horizontal;
        var children = InternalChildren;
        double totalMain = 0;
        double maxCross = 0;
        bool first = true;

        foreach (UIElement child in children)
        {
            if (child.Visibility == Visibility.Collapsed)
                continue;

            child.Measure(constraint);
            var desired = child.DesiredSize;

            if (isHorizontal)
            {
                totalMain += desired.Width + (first ? 0 : spacing);
                maxCross = Math.Max(maxCross, desired.Height);
            }
            else
            {
                totalMain += desired.Height + (first ? 0 : spacing);
                maxCross = Math.Max(maxCross, desired.Width);
            }

            first = false;
        }

        return isHorizontal
            ? new Size(totalMain, maxCross)
            : new Size(maxCross, totalMain);
    }

    protected override Size ArrangeOverride(Size finalSize)
    {
        var spacing = Spacing;
        if (spacing <= 0)
            return base.ArrangeOverride(finalSize);

        var isHorizontal = Orientation == Orientation.Horizontal;
        var children = InternalChildren;
        double offset = 0;

        foreach (UIElement child in children)
        {
            if (child.Visibility == Visibility.Collapsed)
            {
                child.Arrange(new Rect(0, 0, 0, 0));
                continue;
            }

            var desired = child.DesiredSize;
            if (isHorizontal)
            {
                child.Arrange(new Rect(offset, 0, desired.Width, finalSize.Height));
                offset += desired.Width + spacing;
            }
            else
            {
                child.Arrange(new Rect(0, offset, finalSize.Width, desired.Height));
                offset += desired.Height + spacing;
            }
        }

        return finalSize;
    }
}

