namespace ABLogixGitManager.Models;

/// <summary>
/// Describes the result of a dependency detection probe.
/// These statuses map directly to the dependency center UI.
/// </summary>
public enum DependencyStatus
{
    /// <summary>Detection has not started.</summary>
    Unknown,
    /// <summary>Detection probe is in progress.</summary>
    Scanning,
    /// <summary>A supported version was detected and its required validation passed.</summary>
    Ready,
    /// <summary>No usable installation or managed copy was found.</summary>
    Missing,
    /// <summary>A dependency was found but does not meet the validated compatibility policy.</summary>
    Incompatible,
    /// <summary>Scan, verification, or detection failed unexpectedly; diagnostic detail is retained.</summary>
    Failed,
    /// <summary>The selected external action cannot continue without elevation or organizational deployment.</summary>
    AdminRequired,
}

