using System.Diagnostics;
using System.IO;
using ABLogixGitManager.Models;

namespace ABLogixGitManager.Services;

/// <summary>
/// Shells out to l5xgit.exe (and git) to perform commit and pull/restore operations.
/// Streams stdout/stderr back to the caller via the <paramref name="onOutput"/> callback.
/// </summary>
public class L5xGitCliService
{
    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /// <summary>
    /// Validates paths, writes the _L5xGit.yml sidecar, then runs:
    ///   l5xgit commit --acd &lt;acdPath&gt;
    /// Pipes the commit message to stdin.
    /// </summary>
    public async Task CommitAsync(
        RepoEntry repo,
        string l5xGitExePath,
        string commitMessage,
        Action<string> onOutput,
        CancellationToken cancellationToken = default)
    {
        if (!ValidatePaths(repo, l5xGitExePath, onOutput)) return;

        EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);

        // Blank line after the message signals end-of-input to PromptForCommitMessage.
        var stdin = commitMessage.Trim() + "\n\n";

        await RunProcessAsync(
            exePath: l5xGitExePath,
            arguments: ["commit", "--acd", repo.AcdFilePath],
            stdinInput: stdin,
            onOutput: onOutput,
            cancellationToken: cancellationToken);
    }

    /// <summary>
    /// Validates paths, runs:
    ///   git -C &lt;gitRepoPath&gt; pull
    /// and aborts if that step fails, then:
    ///   l5xgit restoreacd --acd &lt;acdPath&gt;
    /// Pipes "y" to stdin to confirm overwriting the existing ACD file.
    /// </summary>
    public async Task PullAndRestoreAsync(
        RepoEntry repo,
        string l5xGitExePath,
        Action<string> onOutput,
        CancellationToken cancellationToken = default)
    {
        if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput)) return;

        onOutput("[git pull] Pulling latest from remote...");
        int gitExitCode = await RunProcessAsync(
            exePath: "git",
            arguments: ["-C", repo.GitRepoPath, "pull"],
            stdinInput: null,
            onOutput: onOutput,
            cancellationToken: cancellationToken);

        if (gitExitCode != 0)
        {
            onOutput($"[abort] git pull failed (exit code {gitExitCode}). Restore cancelled to prevent overwriting with stale content.");
            return;
        }

        if (cancellationToken.IsCancellationRequested) return;

        EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);

        onOutput("[restoreacd] Imploding and converting to ACD...");
        await RunProcessAsync(
            exePath: l5xGitExePath,
            arguments: ["restoreacd", "--acd", repo.AcdFilePath],
            stdinInput: "y\n",   // confirm overwrite of existing ACD
            onOutput: onOutput,
            cancellationToken: cancellationToken);
    }

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    /// <summary>
    /// Validates l5xgit.exe, the ACD file, and the git repo before a commit.
    /// Logs a specific error message for each missing path and returns false on failure.
    /// </summary>
    private static bool ValidatePaths(RepoEntry repo, string l5xGitExePath, Action<string> onOutput)
    {
        if (string.IsNullOrWhiteSpace(l5xGitExePath))
        {
            onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
            return false;
        }

        if (!File.Exists(l5xGitExePath))
        {
            onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
            return false;
        }

        if (!File.Exists(repo.AcdFilePath))
        {
            onOutput($"[error] ACD file not found: {repo.AcdFilePath}");
            return false;
        }

        if (!Directory.Exists(repo.GitRepoPath))
        {
            onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
            return false;
        }

        return true;
    }

    /// <summary>
    /// Validates l5xgit.exe and the git repo before a restore.
    /// The ACD file is not required to exist before restore (it will be created).
    /// </summary>
    private static bool ValidatePathsForRestore(RepoEntry repo, string l5xGitExePath, Action<string> onOutput)
    {
        if (string.IsNullOrWhiteSpace(l5xGitExePath))
        {
            onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
            return false;
        }

        if (!File.Exists(l5xGitExePath))
        {
            onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
            return false;
        }

        if (!Directory.Exists(repo.GitRepoPath))
        {
            onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
            return false;
        }

        return true;
    }

    /// <summary>
    /// Writes (or overwrites) the {name}_L5xGit.yml sidecar file next to the ACD.
    /// The l5xgit CLI looks for this file to know where the git repo lives.
    /// Format mirrors L5xGitConfig YAML serialization.
    /// </summary>
    private static void EnsureL5xGitYml(string acdFilePath, string gitRepoPath)
    {
        var dir = Path.GetDirectoryName(acdFilePath) ?? string.Empty;
        var stem = Path.GetFileNameWithoutExtension(acdFilePath);
        var configPath = Path.Combine(dir, $"{stem}_L5xGit.yml");

        // YamlDotNet uses forward-slash paths; backslashes are valid in YAML
        // scalars but can confuse some parsers — use forward slashes to be safe.
        var normalizedPath = gitRepoPath.Replace('\\', '/');

        var yaml =
            $"destination_path: {normalizedPath}\n" +
            $"prompt_for_commit_message: true\n";

        File.WriteAllText(configPath, yaml);
    }

    /// <summary>
    /// Launches a process using <see cref="ProcessStartInfo.ArgumentList"/> for path-safe
    /// argument handling, streams stdout/stderr to <paramref name="onOutput"/>, and returns
    /// the process exit code.
    /// </summary>
    private static async Task<int> RunProcessAsync(
        string exePath,
        IEnumerable<string> arguments,
        string? stdinInput,
        Action<string> onOutput,
        CancellationToken cancellationToken)
    {
        var psi = new ProcessStartInfo(exePath)
        {
            RedirectStandardInput = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        foreach (var arg in arguments)
            psi.ArgumentList.Add(arg);

        using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };

        process.OutputDataReceived += (_, e) =>
        {
            if (e.Data is not null) onOutput(e.Data);
        };
        process.ErrorDataReceived += (_, e) =>
        {
            if (e.Data is not null) onOutput($"[stderr] {e.Data}");
        };

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();

        if (stdinInput is not null)
            await process.StandardInput.WriteAsync(stdinInput);

        process.StandardInput.Close();

        await process.WaitForExitAsync(cancellationToken);

        if (process.ExitCode != 0)
            onOutput($"[exit code {process.ExitCode}] Process finished with errors.");
        else
            onOutput("[done] ✓ Completed successfully.");

        return process.ExitCode;
    }
}

