using System.Globalization;
using System.Windows.Data;
using System.Windows.Media;
using ABLogixGitManager.Models;

namespace ABLogixGitManager.Converters;

/// <summary>
/// Converts a <see cref="DependencyStatus"/> value to a display icon string (emoji).
/// </summary>
[ValueConversion(typeof(DependencyStatus), typeof(string))]
public class DependencyStatusToIconConverter : IValueConverter
{
    public static readonly DependencyStatusToIconConverter Instance = new();

    public object Convert(object value, Type targetType, object parameter, CultureInfo culture) =>
        value is DependencyStatus status ? StatusIcon(status) : "❓";

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>
        throw new NotSupportedException();

    private static string StatusIcon(DependencyStatus status) => status switch
    {
        DependencyStatus.Ready         => "✅",
        DependencyStatus.Missing       => "⚠️",
        DependencyStatus.Incompatible  => "⚠️",
        DependencyStatus.Scanning      => "⏳",
        DependencyStatus.Failed        => "❌",
        DependencyStatus.AdminRequired => "🔒",
        _                              => "❓",
    };
}

/// <summary>
/// Converts a <see cref="DependencyStatus"/> value to a foreground <see cref="SolidColorBrush"/>.
/// </summary>
[ValueConversion(typeof(DependencyStatus), typeof(Brush))]
public class DependencyStatusToColorConverter : IValueConverter
{
    public static readonly DependencyStatusToColorConverter Instance = new();

    public object Convert(object value, Type targetType, object parameter, CultureInfo culture) =>
        value is DependencyStatus status ? StatusBrush(status) : Brushes.Gray;

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>
        throw new NotSupportedException();

    private static SolidColorBrush StatusBrush(DependencyStatus status) => status switch
    {
        DependencyStatus.Ready         => new SolidColorBrush(Color.FromRgb(0x2E, 0xA0, 0x43)),
        DependencyStatus.Missing       => new SolidColorBrush(Color.FromRgb(0xB3, 0x6A, 0x00)),
        DependencyStatus.Incompatible  => new SolidColorBrush(Color.FromRgb(0xB3, 0x6A, 0x00)),
        DependencyStatus.Scanning      => new SolidColorBrush(Color.FromRgb(0x00, 0x78, 0xD4)),
        DependencyStatus.Failed        => new SolidColorBrush(Color.FromRgb(0xC6, 0x28, 0x28)),
        DependencyStatus.AdminRequired => new SolidColorBrush(Color.FromRgb(0x00, 0x78, 0xD4)),
        _                              => new SolidColorBrush(Color.FromRgb(0x88, 0x88, 0x88)),
    };
}

