    // Log & settings commands
    // -------------------------------------------------------------------------

    [RelayCommand]
    private void ClearLog() => LogOutput = string.Empty;

    [RelayCommand]
    private void SaveL5xGitPath()
    {
        PersistConfig();
        OnPropertyChanged(nameof(IsL5xGitConfigured));
        AppendLog($"[settings] l5xgit.exe path saved: {L5xGitExePath}");
    }

    [RelayCommand]
    private void OpenSettings()
    {
        var window = new SettingsWindow(L5xGitExePath)
        {
            Owner = Application.Current.MainWindow,
        };
        window.ShowDialog();
    }

