147.         {
148.             AppendLog("[cancelled] Operation was cancelled.");
149.         }
150.         catch (Exception ex)
151.         {
152.             AppendLog($"[error] {ex.Message}");
153.         }
154.         finally
155.         {
156.             _cts.Dispose();
157.             _cts = null;
158.             IsBusy = false;
159.         }
160.     }
