163.     private async Task PullAndRestoreAsync()
164.     {
165.         if (SelectedRepo is null) return;
166. 
167.         IsBusy = true;
168.         AppendLog($"--- Pull & Restore started: {SelectedRepo.Name} ---");
169.         _cts = new CancellationTokenSource();
170. 
171.         try
172.         {
173.             await _cliService.PullAndRestoreAsync(
174.                 repo: SelectedRepo.ToModel(),
175.                 l5xGitExePath: L5xGitExePath,
176.                 onOutput: AppendLog,
177.                 cancellationToken: _cts.Token);
178.         }
179.         catch (OperationCanceledException)
180.         {
181.             AppendLog("[cancelled] Operation was cancelled.");
182.         }
183.         catch (Exception ex)
184.         {
185.             AppendLog($"[error] {ex.Message}");
186.         }
187.         finally
188.         {
189.             _cts?.Dispose();
190.             _cts = null;
191.             IsBusy = false;
192.         }
193.     }
