210.     private void SaveL5xGitPath()
211.     {
212.         PersistConfig();
213.         OnPropertyChanged(nameof(IsL5xGitConfigured));
214.         AppendLog($"[settings] l5xgit.exe path saved: {L5xGitExePath}");
215.     }
