230. 
231.     private bool HasSelectedRepo() => SelectedRepo is not null;
232. 
233.     private bool CanCommit() =>
234.         SelectedRepo is not null &&
235.         !string.IsNullOrWhiteSpace(CommitMessage) &&
236.         !IsBusy;
237. 
238.     private bool CanPullAndRestore() =>
239.         SelectedRepo is not null && !IsBusy;
240. 
