242.     // Helpers
243.     // -------------------------------------------------------------------------
244. 
245.     private void AppendLog(string message)
246.     {
247.         var ts = DateTime.Now.ToString("HH:mm:ss");
248.         Application.Current?.Dispatcher.Invoke(() =>
249.         {
250.             LogOutput += $"[{ts}] {message}\n";
251.         });
