using System.IO;
using System.Text.Json;
using ABLogixGitManager.Models;

namespace ABLogixGitManager.Services;

/// <summary>
/// Loads and saves the application configuration to
/// <c>%APPDATA%\ABLogixGitManager\config.json</c>.
/// Returns a default <see cref="AppConfig"/> when the file is absent or unreadable
/// rather than throwing, so the application can still start on a clean machine.
/// </summary>
public class AppConfigService
{
    private static readonly string ConfigDir = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
        "ABLogixGitManager");

    private static readonly string ConfigFilePath = Path.Combine(ConfigDir, "config.json");

    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    /// <summary>
    /// Reads and deserialises the config file.
    /// Returns <see cref="AppConfig.Default"/> if the file is missing or corrupt.
    /// </summary>
    public AppConfig Load()
    {
        if (!File.Exists(ConfigFilePath))
        {
            AppLogger.Info($"No config file found at {ConfigFilePath}; using defaults.");
            return new AppConfig();
        }

        try
        {
            var json = File.ReadAllText(ConfigFilePath);
            var config = JsonSerializer.Deserialize<AppConfig>(json, JsonOptions) ?? new AppConfig();
            AppLogger.Info($"Config loaded from {ConfigFilePath} ({config.Repos.Count} repo(s)).");
            return config;
        }
        catch (Exception ex)
        {
            AppLogger.Error($"Failed to read config file {ConfigFilePath}; using defaults.", ex);
            return new AppConfig();
        }
    }

    /// <summary>
    /// Serialises and writes the configuration to disk, creating the directory if needed.
    /// Logs and rethrows on failure so the caller can surface the error to the user.
    /// </summary>
    /// <param name="config">The configuration to persist.</param>
    public void Save(AppConfig config)
    {
        try
        {
            Directory.CreateDirectory(ConfigDir);
            File.WriteAllText(ConfigFilePath, JsonSerializer.Serialize(config, JsonOptions));
            AppLogger.Info($"Config saved to {ConfigFilePath}.");
        }
        catch (Exception ex)
        {
            AppLogger.Error($"Failed to save config to {ConfigFilePath}.", ex);
            throw;
        }
    }
}

