using System.Diagnostics;
using System.IO;
using ABLogixGitManager.Models;

namespace ABLogixGitManager.Services;

/// <summary>
/// Shells out to l5xgit.exe (and git) to perform commit and pull/restore operations.
/// All operations are async, respect cancellation, and stream stdout/stderr back to the
/// caller via the <paramref name="onOutput"/> callback.
/// </summary>
/// <remarks>
/// Every public method logs its start, completion, validation failures, and exit codes
/// to <see cref="AppLogger"/> so diagnostics are available even when the application
/// is run without a terminal.
/// </remarks>
public class L5xGitCliService
{
    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /// <summary>
    /// Validates paths, writes the _L5xGit.yml sidecar, then runs:
    ///   l5xgit commit --acd &lt;acdPath&gt;
    /// Pipes the commit message to stdin.
    /// </summary>
    /// <param name="repo">Repository entry containing ACD and git paths.</param>
    /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
    /// <param name="commitMessage">Commit message text supplied by the user.</param>
    /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
    /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
    public async Task CommitAsync(
        RepoEntry repo,
        string l5xGitExePath,
        string commitMessage,
        Action<string> onOutput,
        CancellationToken cancellationToken = default)
    {
        AppLogger.Info($"CommitAsync starting for repo '{repo.Name}', ACD: {repo.AcdFilePath}");

        if (!ValidatePaths(repo, l5xGitExePath, onOutput))
        {
            AppLogger.Warn($"CommitAsync aborted — path validation failed for repo '{repo.Name}'.");
            return;
        }

        EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);

        // Blank line after the message signals end-of-input to PromptForCommitMessage.
        var stdin = commitMessage.Trim() + "\n\n";

        int exitCode = await RunProcessAsync(
            exePath: l5xGitExePath,
            arguments: ["commit", "--acd", repo.AcdFilePath],
            stdinInput: stdin,
            onOutput: onOutput,
            cancellationToken: cancellationToken);

        AppLogger.Info($"CommitAsync finished for repo '{repo.Name}' — exit code {exitCode}.");
    }

    /// <summary>
    /// Validates paths, runs:
    ///   git -C &lt;gitRepoPath&gt; pull
    /// and aborts if that step fails, then:
    ///   l5xgit restoreacd --acd &lt;acdPath&gt;
    /// Pipes "y" to stdin to confirm overwriting the existing ACD file.
    /// </summary>
    /// <param name="repo">Repository entry containing ACD and git paths.</param>
    /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
    /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
    /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
    public async Task PullAndRestoreAsync(
        RepoEntry repo,
        string l5xGitExePath,
        Action<string> onOutput,
        CancellationToken cancellationToken = default)
    {
        AppLogger.Info($"PullAndRestoreAsync starting for repo '{repo.Name}', git repo: {repo.GitRepoPath}");

        if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput))
        {
            AppLogger.Warn($"PullAndRestoreAsync aborted — path validation failed for repo '{repo.Name}'.");
            return;
        }

        onOutput("[git pull] Pulling latest from remote...");
        int gitExitCode = await RunProcessAsync(
            exePath: "git",
            arguments: ["-C", repo.GitRepoPath, "pull"],
            stdinInput: null,
            onOutput: onOutput,
            cancellationToken: cancellationToken);

        if (gitExitCode != 0)
        {
            var msg = $"git pull failed (exit code {gitExitCode}). Restore cancelled to prevent overwriting with stale content.";
            onOutput($"[abort] {msg}");
            AppLogger.Error($"PullAndRestoreAsync — {msg} — repo '{repo.Name}'.");
            return;
        }

        if (cancellationToken.IsCancellationRequested)
        {
            AppLogger.Info($"PullAndRestoreAsync cancelled after git pull for repo '{repo.Name}'.");
            return;
        }

        EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);

        onOutput("[restoreacd] Imploding and converting to ACD...");
        int restoreExitCode = await RunProcessAsync(
            exePath: l5xGitExePath,
            arguments: ["restoreacd", "--acd", repo.AcdFilePath],
            stdinInput: "y\n",
            onOutput: onOutput,
            cancellationToken: cancellationToken);

        AppLogger.Info($"PullAndRestoreAsync finished for repo '{repo.Name}' — restoreacd exit code {restoreExitCode}.");
    }

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    /// <summary>
    /// Validates l5xgit.exe, the ACD file, and the git repo before a commit.
    /// Writes a user-readable error to <paramref name="onOutput"/> on failure.
    /// </summary>
    private static bool ValidatePaths(RepoEntry repo, string l5xGitExePath, Action<string> onOutput)
    {
        if (string.IsNullOrWhiteSpace(l5xGitExePath))
        {
            onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
            AppLogger.Warn("ValidatePaths failed — l5xgit.exe path is empty.");
            return false;
        }

        if (!File.Exists(l5xGitExePath))
        {
            onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
            AppLogger.Warn($"ValidatePaths failed — l5xgit.exe not found: {l5xGitExePath}");
            return false;
        }

        if (!File.Exists(repo.AcdFilePath))
        {
            onOutput($"[error] ACD file not found: {repo.AcdFilePath}");
            AppLogger.Warn($"ValidatePaths failed — ACD not found: {repo.AcdFilePath}");
            return false;
        }

        if (!Directory.Exists(repo.GitRepoPath))
        {
            onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
            AppLogger.Warn($"ValidatePaths failed — git repo not found: {repo.GitRepoPath}");
            return false;
        }

        return true;
    }

    /// <summary>
    /// Validates l5xgit.exe and the git repo before a restore.
    /// The ACD file is not required to exist before restore (it will be created by l5xgit).
    /// </summary>
    private static bool ValidatePathsForRestore(RepoEntry repo, string l5xGitExePath, Action<string> onOutput)
    {
        if (string.IsNullOrWhiteSpace(l5xGitExePath))
        {
            onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
            AppLogger.Warn("ValidatePathsForRestore failed — l5xgit.exe path is empty.");
            return false;
        }

        if (!File.Exists(l5xGitExePath))
        {
            onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
            AppLogger.Warn($"ValidatePathsForRestore failed — l5xgit.exe not found: {l5xGitExePath}");
            return false;
        }

        if (!Directory.Exists(repo.GitRepoPath))
        {
            onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
            AppLogger.Warn($"ValidatePathsForRestore failed — git repo not found: {repo.GitRepoPath}");
            return false;
        }

        return true;
    }

    /// <summary>
    /// Writes (or overwrites) the {name}_L5xGit.yml sidecar file next to the ACD.
    /// This file tells l5xgit where the git repository lives and enables commit message prompting.
    /// </summary>
    private static void EnsureL5xGitYml(string acdFilePath, string gitRepoPath)
    {
        var dir = Path.GetDirectoryName(acdFilePath) ?? string.Empty;
        var stem = Path.GetFileNameWithoutExtension(acdFilePath);
        var configPath = Path.Combine(dir, $"{stem}_L5xGit.yml");

        // l5xgit expects forward slashes in destination_path.
        var normalizedPath = gitRepoPath.Replace('\\', '/');

        var yaml =
            $"destination_path: {normalizedPath}\n" +
            $"prompt_for_commit_message: true\n";

        File.WriteAllText(configPath, yaml);
        AppLogger.Info($"Wrote l5xgit sidecar: {configPath}");
    }

    /// <summary>
    /// Launches a process using <see cref="ProcessStartInfo.ArgumentList"/> for path-safe
    /// argument handling, streams stdout/stderr to <paramref name="onOutput"/>, and returns
    /// the process exit code.
    /// </summary>
    /// <remarks>
    /// Using <see cref="ProcessStartInfo.ArgumentList"/> instead of <see cref="ProcessStartInfo.Arguments"/>
    /// prevents shell injection and handles paths with spaces without manual quoting.
    /// </remarks>
    private static async Task<int> RunProcessAsync(
        string exePath,
        IEnumerable<string> arguments,
        string? stdinInput,
        Action<string> onOutput,
        CancellationToken cancellationToken)
    {
        var argList = arguments.ToList();
        AppLogger.Info($"Launching: {exePath} {string.Join(" ", argList.Select(a => $"\"{a}\""))}");

        var psi = new ProcessStartInfo(exePath)
        {
            RedirectStandardInput = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        foreach (var arg in argList)
            psi.ArgumentList.Add(arg);

        using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };

        process.OutputDataReceived += (_, e) =>
        {
            if (e.Data is not null) onOutput(e.Data);
        };
        process.ErrorDataReceived += (_, e) =>
        {
            if (e.Data is not null) onOutput($"[stderr] {e.Data}");
        };

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();

        if (stdinInput is not null)
            await process.StandardInput.WriteAsync(stdinInput);

        process.StandardInput.Close();

        await process.WaitForExitAsync(cancellationToken);

        if (process.ExitCode != 0)
        {
            onOutput($"[exit code {process.ExitCode}] Process finished with errors.");
            AppLogger.Warn($"Process '{exePath}' exited with code {process.ExitCode}.");
        }
        else
        {
            onOutput("[done] ✓ Completed successfully.");
            AppLogger.Info($"Process '{exePath}' completed successfully.");
        }

        return process.ExitCode;
    }
}

