using System.Collections.ObjectModel;
using System.IO;
using System.Windows;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using ABLogixGitManager.Models;
using ABLogixGitManager.Services;
using ABLogixGitManager.Views;

namespace ABLogixGitManager.ViewModels;

/// <summary>
/// Primary view model for <see cref="MainWindow"/>.
/// Manages the repository list, git operations, configuration persistence,
/// and the in-window log output.
/// </summary>
public partial class MainViewModel : ObservableObject
{
    private readonly AppConfigService _configService = new();
    private readonly L5xGitCliService _cliService = new();
    private AppConfig _config;
    private CancellationTokenSource? _cts;

    // -------------------------------------------------------------------------
    // Observable properties
    // -------------------------------------------------------------------------

    /// <summary>The list of configured repository entries displayed in the main list.</summary>
    [ObservableProperty]
    private ObservableCollection<RepoEntryViewModel> _repos = [];

    /// <summary>The currently selected repository entry, or <c>null</c> when nothing is selected.</summary>
    [ObservableProperty]
    [NotifyCanExecuteChangedFor(nameof(CommitCommand))]
    [NotifyCanExecuteChangedFor(nameof(PullAndRestoreCommand))]
    [NotifyCanExecuteChangedFor(nameof(EditRepoCommand))]
    [NotifyCanExecuteChangedFor(nameof(RemoveRepoCommand))]
    private RepoEntryViewModel? _selectedRepo;

    /// <summary>The commit message entered by the user before triggering a commit.</summary>
    [ObservableProperty]
    [NotifyCanExecuteChangedFor(nameof(CommitCommand))]
    private string _commitMessage = string.Empty;

    /// <summary>Accumulated log text displayed in the output panel.</summary>
    [ObservableProperty]
    private string _logOutput = string.Empty;

    /// <summary>
    /// <c>true</c> while a git operation is in progress.
    /// Disables operation buttons and enables the Cancel button.
    /// </summary>
    [ObservableProperty]
    [NotifyCanExecuteChangedFor(nameof(CommitCommand))]
    [NotifyCanExecuteChangedFor(nameof(PullAndRestoreCommand))]
    [NotifyCanExecuteChangedFor(nameof(CancelOperationCommand))]
    private bool _isBusy;

    /// <summary>
    /// Configured path to l5xgit.exe. Changing this property updates
    /// <see cref="IsL5xGitConfigured"/> and re-evaluates command availability.
    /// </summary>
    [ObservableProperty]
    [NotifyPropertyChangedFor(nameof(IsL5xGitConfigured))]
    [NotifyCanExecuteChangedFor(nameof(CommitCommand))]
    [NotifyCanExecuteChangedFor(nameof(PullAndRestoreCommand))]
    private string _l5xGitExePath = string.Empty;

    /// <summary>True when l5xgit.exe is configured and the file exists on disk.</summary>
    public bool IsL5xGitConfigured =>
        !string.IsNullOrWhiteSpace(L5xGitExePath) && File.Exists(L5xGitExePath);

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    /// <summary>
    /// Loads the persisted configuration and populates the repository list.
    /// </summary>
    public MainViewModel()
    {
        _config = _configService.Load();
        L5xGitExePath = _config.L5xGitExePath;

        foreach (var repo in _config.Repos)
            Repos.Add(new RepoEntryViewModel(repo));

        AppLogger.Info($"MainViewModel initialised — {Repos.Count} repo(s) loaded, l5xgit configured: {IsL5xGitConfigured}.");
    }

    // -------------------------------------------------------------------------
    // Repo management commands
    // -------------------------------------------------------------------------

    /// <summary>Opens the Add/Edit dialog in Add mode and appends the new entry.</summary>
    [RelayCommand]
    private void AddRepo()
    {
        var dialog = new AddEditRepoWindow();
        if (dialog.ShowDialog() == true && dialog.Result is not null)
        {
            var vm = new RepoEntryViewModel(dialog.Result);
            Repos.Add(vm);
            SelectedRepo = vm;
            PersistConfig();
            AppLogger.Info($"Repo added: '{dialog.Result.Name}'.");
        }
    }

    /// <summary>Opens the Add/Edit dialog pre-populated with the selected entry.</summary>
    [RelayCommand(CanExecute = nameof(HasSelectedRepo))]
    private void EditRepo()
    {
        if (SelectedRepo is null) return;

        var dialog = new AddEditRepoWindow(SelectedRepo.ToModel());
        if (dialog.ShowDialog() == true && dialog.Result is not null)
        {
            var idx = Repos.IndexOf(SelectedRepo);
            var updated = new RepoEntryViewModel(dialog.Result);
            Repos[idx] = updated;
            SelectedRepo = updated;
            PersistConfig();
            AppLogger.Info($"Repo edited: '{dialog.Result.Name}'.");
        }
    }

    /// <summary>Prompts for confirmation then removes the selected entry from the list.</summary>
    [RelayCommand(CanExecute = nameof(HasSelectedRepo))]
    private void RemoveRepo()
    {
        if (SelectedRepo is null) return;

        var name = SelectedRepo.Name;
        var result = MessageBox.Show(
            $"Remove \"{name}\" from the list?\n\nThis will not delete any files.",
            "Remove Repo",
            MessageBoxButton.YesNo,
            MessageBoxImage.Question);

        if (result != MessageBoxResult.Yes) return;

        Repos.Remove(SelectedRepo);
        SelectedRepo = null;
        PersistConfig();
        AppLogger.Info($"Repo removed: '{name}'.");
    }

    // -------------------------------------------------------------------------
    // Git operations
    // -------------------------------------------------------------------------

    /// <summary>
    /// Commits the selected ACD to its git repository using l5xgit.
    /// The commit message is piped to l5xgit stdin.
    /// </summary>
    [RelayCommand(CanExecute = nameof(CanCommit))]
    private async Task CommitAsync()
    {
        if (SelectedRepo is null) return;

        IsBusy = true;
        AppendLog($"--- Commit started: {SelectedRepo.Name} ---");
        AppLogger.Info($"CommitAsync initiated by user for repo '{SelectedRepo.Name}'.");
        _cts = new CancellationTokenSource();

        try
        {
            await _cliService.CommitAsync(
                repo: SelectedRepo.ToModel(),
                l5xGitExePath: L5xGitExePath,
                commitMessage: CommitMessage,
                onOutput: AppendLog,
                cancellationToken: _cts.Token);

            if (!_cts.IsCancellationRequested)
                CommitMessage = string.Empty;
        }
        catch (OperationCanceledException)
        {
            AppendLog("[cancelled] Operation was cancelled.");
            AppLogger.Info($"CommitAsync cancelled for repo '{SelectedRepo?.Name}'.");
        }
        catch (Exception ex)
        {
            AppendLog($"[error] {ex.Message}");
            AppLogger.Error($"CommitAsync failed for repo '{SelectedRepo?.Name}'.", ex);
        }
        finally
        {
            _cts.Dispose();
            _cts = null;
            IsBusy = false;
        }
    }

    /// <summary>
    /// Pulls the latest commit from the remote and restores the ACD file using l5xgit.
    /// Aborts if the git pull step fails to prevent overwriting with stale content.
    /// </summary>
    [RelayCommand(CanExecute = nameof(CanPullAndRestore))]
    private async Task PullAndRestoreAsync()
    {
        if (SelectedRepo is null) return;

        IsBusy = true;
        AppendLog($"--- Pull & Restore started: {SelectedRepo.Name} ---");
        AppLogger.Info($"PullAndRestoreAsync initiated by user for repo '{SelectedRepo.Name}'.");
        _cts = new CancellationTokenSource();

        try
        {
            await _cliService.PullAndRestoreAsync(
                repo: SelectedRepo.ToModel(),
                l5xGitExePath: L5xGitExePath,
                onOutput: AppendLog,
                cancellationToken: _cts.Token);
        }
        catch (OperationCanceledException)
        {
            AppendLog("[cancelled] Operation was cancelled.");
            AppLogger.Info($"PullAndRestoreAsync cancelled for repo '{SelectedRepo?.Name}'.");
        }
        catch (Exception ex)
        {
            AppendLog($"[error] {ex.Message}");
            AppLogger.Error($"PullAndRestoreAsync failed for repo '{SelectedRepo?.Name}'.", ex);
        }
        finally
        {
            _cts?.Dispose();
            _cts = null;
            IsBusy = false;
        }
    }

    // -------------------------------------------------------------------------
    // Log & settings commands
    // -------------------------------------------------------------------------

    /// <summary>Clears the in-window log output panel.</summary>
    [RelayCommand]
    private void ClearLog() => LogOutput = string.Empty;

    /// <summary>
    /// Requests cancellation of the active git operation.
    /// The operation stops after its current subprocess step completes.
    /// </summary>
    [RelayCommand(CanExecute = nameof(IsBusy))]
    private void CancelOperation()
    {
        _cts?.Cancel();
        AppendLog("[cancelling] Cancel requested — waiting for current step to stop…");
        AppLogger.Info("User requested operation cancellation.");
    }

    /// <summary>
    /// Saves the current <see cref="L5xGitExePath"/> to configuration.
    /// Updates <see cref="IsL5xGitConfigured"/> so the warning card hides.
    /// </summary>
    [RelayCommand]
    private void SaveL5xGitPath()
    {
        PersistConfig();
        OnPropertyChanged(nameof(IsL5xGitConfigured));
        AppendLog($"[settings] l5xgit.exe path saved: {L5xGitExePath}");
        AppLogger.Info($"l5xgit.exe path saved: {L5xGitExePath}");
    }

    /// <summary>Opens the Settings / Dependency Center window as a modal dialog.</summary>
    [RelayCommand]
    private void OpenSettings()
    {
        AppLogger.Info("Opening Settings window.");
        var window = new SettingsWindow(L5xGitExePath)
        {
            Owner = Application.Current.MainWindow,
        };
        window.ShowDialog();
    }

    // -------------------------------------------------------------------------
    // CanExecute predicates
    // -------------------------------------------------------------------------

    private bool HasSelectedRepo() => SelectedRepo is not null;

    private bool CanCommit() =>
        SelectedRepo is not null &&
        !string.IsNullOrWhiteSpace(CommitMessage) &&
        !IsBusy;

    private bool CanPullAndRestore() =>
        SelectedRepo is not null && !IsBusy;

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    /// <summary>
    /// Appends a timestamped line to <see cref="LogOutput"/> on the UI thread.
    /// </summary>
    private void AppendLog(string message)
    {
        var ts = DateTime.Now.ToString("HH:mm:ss");
        Application.Current?.Dispatcher.Invoke(() =>
        {
            LogOutput += $"[{ts}] {message}\n";
        });
    }

    /// <summary>
    /// Writes the current in-memory state back to <c>config.json</c>.
    /// </summary>
    private void PersistConfig()
    {
        _config.L5xGitExePath = L5xGitExePath;
        _config.Repos = [.. Repos.Select(r => r.ToModel())];
        _configService.Save(_config);
    }
}

